document.addEventListener("astro:page-load",()=>{const n=document.getElementById("copy-link-btn");n&&n.addEventListener("click",()=>{navigator.clipboard.writeText(window.location.href);const t=n.querySelector("span");if(t){const e=t.textContent;t.textContent=" Copied!",setTimeout(()=>{t.textContent=e},2e3)}});const o=document.getElementById("reading-progress");if(o){let t=!1;const e=()=>{const r=window.scrollY,i=document.documentElement.scrollHeight-window.innerHeight;if(i>0){const c=Math.min(r/i*100,100);o.style.width=c+"%"}t=!1},s=()=>{t||(requestAnimationFrame(e),t=!0)};window.addEventListener("scroll",s,{passive:!0}),e()}});
